1	#!/bin/bash
     2	fail=0
     3	d=$(mktemp -d)
     4	mkdir -p "$d/logs"
     5	echo one > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 20261001
     6	echo two > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 20261002
     7	[ "$(cat "$d/logs/app.log.1")" = two ] || { echo "app.log.1"; fail=1; }
     8	[ "$(cat "$d/logs/app.log.2")" = one ] || { echo "app.log.2"; fail=1; }
     9	[ "$(cat "$d/archive/app.log.20261002")" = two ] || { echo "archive"; fail=1; }
    10	rm -rf "$d"
    11	for i in 3 4 5 6; do echo n$i > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 2026100$i; done
    12	touch "$d/logs/app.log.bak" "$d/archive/other.20200101"
    13	echo n7 > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 20261007
    14	[ "$(ls "$d/logs" | grep -c '^app.log\.[0-9]')" = 3 ] || { echo "local keep"; fail=1; }

